    pl=apis.spotify.show_playlist(playlist_id=pid, access_token=access_token)
    title=pl.get('title')
    song_objs=pl.get('songs',[])
    # Determine songs with release year > 2021
    for s in song_objs:
        sid=s['id']
        ds=apis.spotify.show_song(song_id=sid)
        year=parse_year(ds.get('release_date'))
        release_year_debug.append((pid,title,sid,s.get('title'),ds.get('release_date'),year))
        if year is not None and year>2021:
